<div class="page-heading"><div><span class="eyebrow">Account settings</span><h1>My profile</h1><p class="muted">Update your contact details or change your password.</p></div><?= badge(choices('type')[$user['type']]) ?></div>
<form class="card stack profile-form" method="post" action="<?= e(url('action')) ?>" data-submit><?= csrf() ?><input type="hidden" name="action" value="profile"><div class="form-grid"><?= field('name','Full name',$user['name'],['required'=>true,'maxlength'=>80,'autocomplete'=>'name']) ?><?= field('email','Email address',$user['email'],['type'=>'email','required'=>true,'maxlength'=>100,'autocomplete'=>'email']) ?><?= field('contact','Contact number',$user['contact'],['type'=>'tel','maxlength'=>20,'autocomplete'=>'tel']) ?><div class="field"><span class="field-label">Username</span><strong><?= e($user['username']) ?></strong><small>Ask your administrator to change your username or barangay assignment.</small></div></div><h2>Change password</h2><p class="muted">Leave these fields blank to keep your current password.</p><?= field('current_password','Current password','',['type'=>'password','autocomplete'=>'current-password']) ?><?= field('new_password','New password','',['type'=>'password','autocomplete'=>'new-password','maxlength'=>72,'minlength'=>12,'hint'=>'Use 12–72 bytes.']) ?><?= field('cpassword','Confirm new password','',['type'=>'password','autocomplete'=>'new-password','maxlength'=>72]) ?><?= button('Save profile') ?></form>
